/**
 * Pre-encoded base64 Data URIs for PolyLance real brand assets.
 * Used inside canonical SVG certificate renderer so that canvas PNG/PDF exports
 * never suffer from cross-origin/external URL taint issues or missing asset paths.
 */
export const POLYLANCE_LOGO_DATA_URI = "data:image/png;base64,";

export const POLYLANCE_SCRIPT_WORDMARK_DATA_URI = "data:image/png;base64,";
